<script>
(function(){
  var ids=['dp5-bc','dp5-imgcol','dp5-info'];
  function trigger(){ids.forEach(function(id){var el=document.getElementById(id);if(el)el.classList.add('dp5-vis');});}
  if(document.readyState==='complete'){trigger();}else{window.addEventListener('load',trigger);}
  var mainImg=document.getElementById('dp5-main-img');
  var thumbs=document.querySelectorAll('.dp5-hero__thumb');
  thumbs.forEach(function(thumb){
    thumb.addEventListener('click',function(){
      var src=thumb.getAttribute('data-src');
      if(src&&mainImg){mainImg.style.opacity='0';mainImg.style.transition='opacity .2s ease';setTimeout(function(){mainImg.src=src;mainImg.style.opacity='1';},180);}
      thumbs.forEach(function(t){t.classList.remove('dp5-hero__thumb--active');});
      thumb.classList.add('dp5-hero__thumb--active');
    });
  });
